// Specification function - defines triangular number inductively
// In a real verification context, this would be a specification-only function
// For this implementation, we provide a regular function that computes the value
pub fn triangle(n: u32) -> u32 {
    n * (n + 1) / 2
}

// Proof of monotonicity - in a verification context this would be a proof function
// For this implementation, we provide a regular function that asserts the property
pub fn triangle_is_monotonic(i: u32, j: u32) {
    // This would contain proof logic in a verification context
    // For regular Rust, we can assert the property holds
    assert!(i <= j, "i must be less than or equal to j for monotonicity check");
    assert!(triangle(i) <= triangle(j), "triangle function is not monotonic");
}

// Tail-recursive implementation that computes triangular number
// Assumes: idx <= n, sum initially holds triangle(idx)
// Guarantee: sum will be updated to triangle(n) on completion
pub fn tail_triangle(n: u32, idx: u32, sum: &mut u32) {
    // Base case: if we've reached the target, we're done
    if idx == n {
        return;
    }
    
    // Recursive case: add the next number to the sum and recurse
    // The next triangular number is current sum + (idx + 1)
    *sum += idx + 1;
    
    // Tail-recursive call with updated index
    tail_triangle(n, idx + 1, sum);
}

// Alternative iterative implementation for comparison
pub fn tail_triangle_iterative(n: u32, idx: u32, sum: &mut u32) {
    let mut current_idx = idx;
    let mut current_sum = *sum;
    
    while current_idx < n {
        current_idx += 1;
        current_sum += current_idx;
    }
    
    *sum = current_sum;
}

